/**
 * Accounting reports in the accountant's (Bukku) layout: centred title, firm and period; account
 * codes; section headings with TOTAL rows; GROSS PROFIT / NET PROFIT; ledgers grouped by account
 * or client with opening and running balances; "Generated by … with SHCO Portal" and page numbers.
 *
 * Pure: builders take plain inputs (accounts, ledger postings, invoices…) and return a report
 * model; reportHtml() prints it, reportSheet() lays it out for Excel the same way.
 */

export type AType = 'Asset' | 'Liability' | 'Equity' | 'Income' | 'Expense';
export interface Acct { key: string; code: string; name: string; type: AType }
/** One ledger posting: `amount` debited to `dr`, credited to `cr` (account keys). */
export interface Posting { t: number; no: string; contact: string; tags: string; desc: string; dr: string; cr: string; amount: number }

export type Cell = string | number | null;
type RowStyle = 'head' | 'line' | 'total' | 'grand' | 'gap' | 'opening';
interface Row { style: RowStyle; cells: Cell[]; indent?: number }
interface Col { label: string; align?: 'left' | 'right'; width?: string; money?: boolean }
export interface Report { title: string; firm: string; period: string; sub?: string; cols: Col[]; rows: Row[]; landscape?: boolean; rm?: boolean }

/* ------------------------------------------------------------------ numbers and dates */

const r2 = (n: number) => Math.round((n + Number.EPSILON) * 100) / 100;
/** RM1,234.00 / -RM23,066.57 (Bukku style); plain 1,234.00 when `rm` is false. */
export const money = (n: number, rm = true) => {
  const v = r2(n);
  const s = Math.abs(v).toLocaleString('en-MY', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return (v < 0 ? '-' : '') + (rm ? 'RM' : '') + s;
};
const dmy = (t: number) => { const d = new Date(t); return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear(); };
const dmyShort = (t: number) => dmy(t).replace(/\/(\d{2})(\d{2})$/, '/$2');

/* ------------------------------------------------------------------ accounts */

/** Parent account of a Bukku-style code: 3500-0000-00 → 3500-0000; 5000-1000 → 5000-0000. */
export const parentCode = (code: string): string | null => {
  const p = String(code).split('-');
  if (p.length === 3) return p[0] + '-' + p[1];
  if (p.length === 2 && !/^0+$/.test(p[1])) return p[0] + '-' + '0'.repeat(p[1].length);
  return null;
};

/** Report section of an account (Bukku: 2… non-current assets, 6… cost of sales, 7… other income). */
const sectionOf = (a: Acct): string => {
  const first = a.code.charAt(0);
  const bukku = /^[0-9][0-9A-Z]{3}-/.test(a.code);
  if (a.type === 'Asset') return bukku && first === '2' ? 'Non-Current Assets' : 'Current Assets';
  if (a.type === 'Liability') return bukku && first === '2' ? 'Non-Current Liabilities' : 'Current Liabilities';
  if (a.type === 'Equity') return 'Equity';
  if (a.type === 'Income') return bukku && first === '7' ? 'Other Income' : 'Income';
  return bukku && first === '6' ? 'Cost of Sales' : 'Expenses';
};

/** Signed balance per account key (debit +, credit −) for postings with from ≤ t ≤ to. */
const balances = (ps: Posting[], from = -Infinity, to = Infinity) => {
  const b = new Map<string, number>();
  for (const p of ps) {
    if (p.t < from || p.t > to) continue;
    b.set(p.dr, (b.get(p.dr) || 0) + p.amount);
    b.set(p.cr, (b.get(p.cr) || 0) - p.amount);
  }
  return b;
};
/** Natural sign: assets and expenses debit-positive, the rest credit-positive. */
const natural = (a: Acct, v: number) => (a.type === 'Asset' || a.type === 'Expense' ? v : -v);

/** Lines for one section: accounts with a balance, grouped under their parent with a TOTAL. */
const sectionLines = (accts: Acct[], amount: (a: Acct) => number, valueCells: (v: number) => Cell[], blankCells: Cell[]): { rows: Row[]; total: number } => {
  const byCode = new Map(accts.map((a) => [a.code, a]));
  const shown = accts.filter((a) => Math.abs(amount(a)) > 0.004).sort((x, y) => x.code.localeCompare(y.code));
  const rows: Row[] = [];
  let total = 0;
  const groups = new Map<string, Acct[]>();
  const order: string[] = [];
  for (const a of shown) {
    const p = parentCode(a.code);
    const g = p && byCode.has(p) && p !== a.code ? p : a.code;
    if (!groups.has(g)) { groups.set(g, []); order.push(g); }
    groups.get(g)!.push(a);
  }
  for (const g of order) {
    const kids = groups.get(g)!;
    const parent = byCode.get(g);
    if (kids.length === 1 && kids[0].code === g) {
      const v = amount(kids[0]); total += v;
      rows.push({ style: 'line', indent: 1, cells: [kids[0].code, kids[0].name, ...valueCells(v)] });
      continue;
    }
    rows.push({ style: 'line', indent: 1, cells: [g, parent?.name || g, ...blankCells] });
    let sub = 0;
    for (const a of kids) { const v = amount(a); sub += v; rows.push({ style: 'line', indent: 2, cells: [a.code, a.name, ...valueCells(v)] }); }
    total += sub;
    rows.push({ style: 'total', indent: 2, cells: ['TOTAL', '', ...valueCells(sub)] });
  }
  return { rows, total };
};

/* ------------------------------------------------------------------ Profit & Loss */

export function profitAndLoss(firm: string, accts: Acct[], ps: Posting[], from: number, to: number): Report {
  const b = balances(ps, from, to);
  const amt = (a: Acct) => r2(natural(a, b.get(a.key) || 0));
  const inSec = (s: string) => accts.filter((a) => sectionOf(a) === s);
  const income = sectionLines(inSec('Income'), amt, (v) => [v, null], [null, null]);
  const pct = (v: number) => (income.total ? r2((v / income.total) * 100) : 0);
  const withPct = (rows: Row[]) => rows.map((r) => (r.style === 'gap' || r.style === 'head' ? r : { ...r, cells: [r.cells[0], r.cells[1], r.cells[2], typeof r.cells[2] === 'number' ? pct(r.cells[2] as number) : null] }));
  const cos = sectionLines(inSec('Cost of Sales'), amt, (v) => [v, null], [null, null]);
  const other = sectionLines(inSec('Other Income'), amt, (v) => [v, null], [null, null]);
  const exp = sectionLines(inSec('Expenses'), amt, (v) => [v, null], [null, null]);
  const gross = income.total - cos.total;
  const net = gross + other.total - exp.total;
  const block = (label: string, s: { rows: Row[]; total: number }): Row[] => [
    { style: 'head', cells: [label, '', null, null] },
    ...withPct(s.rows),
    { style: 'total', indent: 1, cells: ['TOTAL', '', s.total, pct(s.total)] },
  ];
  const rows: Row[] = [
    ...block('Income', income),
    { style: 'gap', cells: [] },
    ...block('Less: Cost of Sales', cos),
    { style: 'grand', cells: ['GROSS PROFIT', '', gross, pct(gross)] },
    { style: 'gap', cells: [] },
    ...block('Other Income', other),
    { style: 'gap', cells: [] },
    ...block('Less: Expenses', exp),
    { style: 'grand', cells: ['NET PROFIT', '', net, pct(net)] },
  ];
  return {
    title: 'Profit & Loss', firm, period: dmy(from) + ' - ' + dmy(to),
    cols: [{ label: '', width: '18%' }, { label: '', width: '40%' }, { label: dmyShort(from) + ' - ' + dmyShort(to), align: 'right', money: true }, { label: '%', align: 'right' }],
    rows,
  };
}

/* ------------------------------------------------------------------ Balance Sheet */

export function balanceSheet(firm: string, accts: Acct[], ps: Posting[], asAt: number, fyStart: number, retainedCode = '1500-0000'): Report {
  const all = balances(ps, -Infinity, asAt);
  const amt = (a: Acct) => r2(natural(a, all.get(a.key) || 0));
  const isPL = (a: Acct) => a.type === 'Income' || a.type === 'Expense';
  const plOf = (b: Map<string, number>) => accts.filter(isPL).reduce((s, a) => s - (b.get(a.key) || 0), 0);
  const cyEarnings = r2(plOf(balances(ps, fyStart, asAt)));
  const priorEarnings = r2(plOf(balances(ps, -Infinity, fyStart - 1)));
  const sec = (s: string) => sectionLines(accts.filter((a) => sectionOf(a) === s), amt, (v) => [v], [null]);
  const total = (label: string, v: number): Row => ({ style: 'total', indent: 1, cells: [label, '', v] });
  const nca = sec('Non-Current Assets'), oa = { rows: [] as Row[], total: 0 }, ca = sec('Current Assets');
  const ncl = sec('Non-Current Liabilities'), cl = sec('Current Liabilities');
  const retained = accts.find((a) => a.code === retainedCode);
  const eqAccts = accts.filter((a) => sectionOf(a) === 'Equity' && a.code !== retainedCode);
  const eq = sectionLines(eqAccts, amt, (v) => [v], [null]);
  const retainedTotal = r2((retained ? amt(retained) : 0) + priorEarnings);
  const equity = r2(cyEarnings + eq.total + retainedTotal);
  const assets = r2(nca.total + oa.total + ca.total), liab = r2(ncl.total + cl.total);
  const rows: Row[] = [
    { style: 'head', cells: ['Non-Current Assets', '', null] }, ...nca.rows, total('TOTAL', nca.total), { style: 'gap', cells: [] },
    { style: 'head', cells: ['Other Assets', '', null] }, total('TOTAL', 0), { style: 'gap', cells: [] },
    { style: 'head', cells: ['Current Assets', '', null] }, ...ca.rows, total('TOTAL', ca.total),
    { style: 'grand', cells: ['TOTAL ASSETS', '', assets] }, { style: 'gap', cells: [] },
    { style: 'head', cells: ['Non-Current Liabilities', '', null] }, ...ncl.rows, total('TOTAL', ncl.total), { style: 'gap', cells: [] },
    { style: 'head', cells: ['Current Liabilities', '', null] }, ...cl.rows, total('TOTAL', cl.total),
    { style: 'grand', cells: ['TOTAL LIABILITIES', '', liab] }, { style: 'gap', cells: [] },
    { style: 'head', cells: ['Equity', '', null] },
    { style: 'line', indent: 1, cells: ['-', 'Current Year Earnings', cyEarnings] },
    ...eq.rows,
    { style: 'line', indent: 1, cells: [retained?.code || '-', retained?.name || 'Retained earnings', retainedTotal] },
    { style: 'grand', cells: ['TOTAL EQUITY', '', equity] }, { style: 'gap', cells: [] },
    { style: 'grand', cells: ['TOTAL LIABILITIES + EQUITY', '', r2(liab + equity)] },
  ];
  return { title: 'Balance Sheet', firm, period: 'As of ' + dmy(asAt), cols: [{ label: '', width: '18%' }, { label: '', width: '55%' }, { label: dmy(asAt), align: 'right', money: true }], rows };
}

/* ------------------------------------------------------------------ Trial Balance */

export function trialBalance(firm: string, accts: Acct[], ps: Posting[], asAt: number, fyStart: number, retainedCode = '1500-0000'): Report {
  const isPL = (a: Acct) => a.type === 'Income' || a.type === 'Expense';
  const bs = balances(ps, -Infinity, asAt), cy = balances(ps, fyStart, asAt), prior = balances(ps, -Infinity, fyStart - 1);
  const byCode = new Map(accts.map((a) => [a.code, a]));
  const label = (a: Acct) => { const p = parentCode(a.code); const pa = p ? byCode.get(p) : undefined; return pa && pa !== a ? pa.name + ': ' + a.name : a.name; };
  const priorPL = accts.filter(isPL).reduce((s, a) => s + (prior.get(a.key) || 0), 0);
  const retained = accts.find((a) => a.code === retainedCode);
  let dr = 0, cr = 0;
  const rows: Row[] = [];
  for (const a of [...accts].sort((x, y) => x.code.localeCompare(y.code))) {
    let v = r2(isPL(a) ? cy.get(a.key) || 0 : bs.get(a.key) || 0);
    if (retained && a.key === retained.key) v = r2(v + priorPL);
    if (Math.abs(v) < 0.005) continue;
    if (v > 0) dr += v; else cr -= v;
    rows.push({ style: 'line', cells: [a.code, label(a), v > 0 ? v : '-', v < 0 ? -v : '-'] });
  }
  if (!retained && Math.abs(priorPL) > 0.004) { const v = r2(priorPL); if (v > 0) dr += v; else cr -= v; rows.push({ style: 'line', cells: ['-', 'Retained earnings (previous years)', v > 0 ? v : '-', v < 0 ? -v : '-'] }); }
  rows.push({ style: 'grand', cells: ['TOTAL', '', r2(dr), r2(cr)] });
  return { title: 'Trial Balance', firm, period: 'As of ' + dmy(asAt), cols: [{ label: 'Code', width: '13%' }, { label: 'Account' }, { label: 'Debit', align: 'right', money: true }, { label: 'Credit', align: 'right', money: true }], rows };
}

/* ------------------------------------------------------------------ General Ledger */

export function generalLedger(firm: string, accts: Acct[], ps: Posting[], from: number, to: number): Report {
  const open = balances(ps, -Infinity, from - 1);
  const rows: Row[] = [];
  for (const a of [...accts].sort((x, y) => x.code.localeCompare(y.code))) {
    const mine = ps.filter((p) => p.t >= from && p.t <= to && (p.dr === a.key || p.cr === a.key)).sort((x, y) => x.t - y.t || x.no.localeCompare(y.no));
    const ob = r2(natural(a, open.get(a.key) || 0));
    if (!mine.length && Math.abs(ob) < 0.005) continue;
    rows.push({ style: 'head', cells: [a.code + ' ' + a.name, '', '', '', '', null, null, null] });
    rows.push({ style: 'opening', indent: 1, cells: [dmy(from) + ' Opening Balance', '', '', '', '', null, null, ob] });
    let bal = ob, d = 0, c = 0;
    for (const p of mine) {
      const debit = p.dr === a.key ? p.amount : 0, credit = p.cr === a.key ? p.amount : 0;
      d += debit; c += credit;
      bal = r2(bal + natural(a, debit - credit));
      rows.push({ style: 'line', indent: 1, cells: [dmy(p.t), p.no || '-', p.contact || '-', p.tags || '-', p.desc, debit || null, credit || null, bal] });
    }
    rows.push({ style: 'total', indent: 1, cells: ['TOTAL', '', '', '', '', r2(d), r2(c), null] });
    rows.push({ style: 'gap', cells: [] });
  }
  return {
    title: 'General Ledger', firm, period: dmy(from) + ' - ' + dmy(to), landscape: true,
    cols: [{ label: 'Date', width: '8%' }, { label: 'No.', width: '9%' }, { label: 'Contact', width: '17%' }, { label: 'Tags', width: '11%' }, { label: 'Description' }, { label: 'Debit MYR', align: 'right', money: true }, { label: 'Credit MYR', align: 'right', money: true }, { label: 'Balance MYR', align: 'right', money: true }],
    rows: rows.length ? rows : [{ style: 'line', cells: ['No postings in this period', '', '', '', '', null, null, null] }],
  };
}

/* ------------------------------------------------------------------ Debtor Ledger and Invoice Summary */

export interface DebtorDoc { t: number; client: string; no: string; tags: string; desc: string; debit: number; credit: number }

export function debtorLedger(firm: string, docs: DebtorDoc[], from: number, to: number): Report {
  const clients = [...new Set(docs.map((d) => d.client || 'No client'))].sort((a, b) => a.localeCompare(b));
  const rows: Row[] = [];
  for (const cl of clients) {
    const mine = docs.filter((d) => (d.client || 'No client') === cl);
    const ob = r2(mine.filter((d) => d.t < from).reduce((s, d) => s + d.debit - d.credit, 0));
    const inP = mine.filter((d) => d.t >= from && d.t <= to).sort((x, y) => x.t - y.t || x.no.localeCompare(y.no));
    if (!inP.length && Math.abs(ob) < 0.005) continue;
    rows.push({ style: 'head', cells: [cl, '', '', '', null, null, null] });
    rows.push({ style: 'opening', indent: 1, cells: [dmy(from) + ' Opening Balance', '', '', '', null, null, ob] });
    let bal = ob, dr = 0, cr = 0;
    for (const d of inP) { dr += d.debit; cr += d.credit; bal = r2(bal + d.debit - d.credit); rows.push({ style: 'line', indent: 1, cells: [dmy(d.t), d.no, d.tags || '-', d.desc, d.debit || null, d.credit || null, bal] }); }
    rows.push({ style: 'total', indent: 1, cells: ['TOTAL', '', '', '', r2(dr), r2(cr), null] });
    rows.push({ style: 'gap', cells: [] });
  }
  return {
    title: 'Debtor Ledger', firm, period: dmy(from) + ' - ' + dmy(to), landscape: true,
    cols: [{ label: 'Date', width: '9%' }, { label: 'No.', width: '11%' }, { label: 'Tags', width: '14%' }, { label: 'Description' }, { label: 'Debit MYR', align: 'right', money: true }, { label: 'Credit MYR', align: 'right', money: true }, { label: 'Balance MYR', align: 'right', money: true }],
    rows: rows.length ? rows : [{ style: 'line', cells: ['No invoices or receipts in this period', '', '', '', null, null, null] }],
  };
}

export interface InvoiceLine { t: number; no: string; contact: string; desc: string; amount: number; balance: number }
export function invoiceSummary(firm: string, inv: InvoiceLine[], from: number, to: number): Report {
  const list = inv.filter((i) => i.t >= from && i.t <= to).sort((a, b) => a.t - b.t || a.no.localeCompare(b.no));
  const rows: Row[] = list.map((i) => ({ style: 'line', cells: [dmy(i.t), i.no, i.contact, i.desc, i.amount, i.balance] }));
  rows.push({ style: 'grand', cells: ['TOTAL', '', '', '', r2(list.reduce((s, i) => s + i.amount, 0)), r2(list.reduce((s, i) => s + i.balance, 0))] });
  return {
    title: 'Invoice Summary', firm, period: dmy(from) + ' - ' + dmy(to),
    cols: [{ label: 'Date', width: '11%' }, { label: 'No', width: '11%' }, { label: 'Contact', width: '20%' }, { label: 'Description' }, { label: 'Net Amount', align: 'right', money: true }, { label: 'Net Balance', align: 'right', money: true }],
    rows,
  };
}

/* ------------------------------------------------------------------ Bank Reconciliation */

export interface ReconItem { t: number; no: string; contact: string; desc: string; amount: number }
export function bankReconciliation(firm: string, account: string, asAt: number, portalBalance: number, statement: number | null, notCredited: ReconItem[], unpresented: ReconItem[]): Report {
  const at = dmy(asAt);
  const dep = r2(notCredited.reduce((s, i) => s + i.amount, 0)), chq = r2(unpresented.reduce((s, i) => s + i.amount, 0));
  const item = (i: ReconItem): Row => ({ style: 'line', indent: 1, cells: [dmy(i.t), i.no, i.contact, i.desc, i.amount] });
  const unrec = statement == null ? null : r2(portalBalance - (statement + dep - chq));
  const rows: Row[] = [
    { style: 'head', cells: ['STATEMENT BALANCE AS OF ' + at, '', '', '', statement == null ? 'Not entered' : statement] }, { style: 'gap', cells: [] },
    { style: 'head', cells: ['ADD: DEPOSITS NOT CREDITED BY BANK AS OF ' + at, '', '', '', null] }, ...notCredited.map(item), { style: 'total', indent: 1, cells: ['TOTAL', '', '', '', dep] }, { style: 'gap', cells: [] },
    { style: 'head', cells: ['LESS: UNPRESENTED CHEQUE AS OF ' + at, '', '', '', null] }, ...unpresented.map(item), { style: 'total', indent: 1, cells: ['TOTAL', '', '', '', chq] }, { style: 'gap', cells: [] },
    { style: 'head', cells: ['TOTAL UNRECONCILED AMOUNT AS OF ' + at, '', '', '', unrec == null ? '—' : unrec] },
    { style: 'head', cells: ['BALANCE IN SHCO PORTAL AS OF ' + at, '', '', '', portalBalance] },
  ];
  return { title: 'Bank Reconciliation', firm, period: 'As of ' + at, sub: account, rm: false, cols: [{ label: 'Date', width: '15%' }, { label: 'No', width: '15%' }, { label: 'Contact', width: '18%' }, { label: 'Description' }, { label: 'Amount MYR', align: 'right', money: true }], rows };
}

/* ------------------------------------------------------------------ simple table (other reports) */

const MONEYISH = /^\s*-?\(?\s*(RM\s?)?-?[\d,]+\.\d{2}\)?\s*$/;
export function simpleReport(firm: string, title: string, period: string, cols: string[], body: Cell[][]): Report {
  const right = (i: number) => i > 0 && body.length > 0 && body.every((r) => r[i] == null || r[i] === '' || r[i] === '—' || typeof r[i] === 'number' || MONEYISH.test(String(r[i])));
  return { title, firm, period, cols: cols.map((c, i) => ({ label: c, align: right(i) ? 'right' : 'left', money: body.some((r) => typeof r[i] === 'number') })), rows: body.length ? body.map((c) => ({ style: 'line', cells: c })) : [{ style: 'line', cells: ['No records for this period', ...cols.slice(1).map(() => '')] }] };
}

/* ------------------------------------------------------------------ output */

const esc = (s: unknown) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmtCell = (r: Report, c: Cell, col?: Col) => (c == null ? '' : typeof c === 'number' ? (col?.label === '%' ? r2(c).toFixed(2) : money(c, r.rm !== false)) : esc(c));

/** The report as printable HTML (A4, Bukku layout). `generatedBy` goes in the footer. */
export function reportHtml(r: Report, generatedBy: string, when = new Date()): string {
  const stamp = dmy(when.getTime()) + ' ' + when.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', hour12: true }).replace(' ', '').toLowerCase();
  const foot = 'Generated by ' + generatedBy + ' on ' + stamp + ' with SHCO Portal';
  const n = r.cols.length;
  const tr = (row: Row) => {
    if (row.style === 'gap') return `<tr class="gap"><td colspan="${n}"></td></tr>`;
    if (row.style === 'head' && row.cells.slice(1).every((c) => c === '' || c == null)) return `<tr class="head"><td colspan="${n}">${esc(row.cells[0])}</td></tr>`;
    if (row.style === 'opening' || row.style === 'grand' || (row.style === 'total' && row.cells[1] === '' && row.cells[0] === 'TOTAL') || row.style === 'head') {
      // first cell spans the text columns up to the first number column
      const firstNum = r.cols.findIndex((c, i) => i > 0 && (c.money || c.label === '%'));
      const span = firstNum > 0 ? firstNum : 1;
      const tds = [`<td colspan="${span}" style="padding-left:${(row.indent || 0) * 18 + 6}px">${esc(row.cells[0])}</td>`];
      for (let i = span; i < n; i++) tds.push(`<td class="${r.cols[i].align === 'right' ? 'r' : ''}">${fmtCell(r, row.cells[i] ?? null, r.cols[i])}</td>`);
      return `<tr class="${row.style}">${tds.join('')}</tr>`;
    }
    return `<tr class="${row.style}">${row.cells.slice(0, n).map((c, i) => `<td class="${r.cols[i]?.align === 'right' ? 'r' : ''}" style="${i === 0 || (i === 1 && (row.indent || 0) > 1) ? 'padding-left:' + ((row.indent || 0) * 18 + 6) + 'px' : ''}">${fmtCell(r, c, r.cols[i])}</td>`).join('')}</tr>`;
  };
  const hasHeads = r.cols.some((c) => c.label);
  return `<style>
@page { size: A4 ${r.landscape ? 'landscape' : 'portrait'}; margin: 16mm 14mm 18mm; @bottom-left { content: "${foot.replace(/"/g, "'")}"; font: 8pt sans-serif; color: #444; } @bottom-right { content: "Page " counter(page) " / " counter(pages); font: 8pt sans-serif; color: #444; } }
.ar { font-family: "Noto Sans", "Segoe UI", -apple-system, Helvetica, Arial, sans-serif; color: #111; font-size: 9pt; }
.ar .t { text-align: center; margin-bottom: 14px; } .ar .t h1 { font-size: 20pt; font-weight: 600; margin: 0; letter-spacing: -.01em; } .ar .t div { font-size: 11.5pt; line-height: 1.35; }
.ar table { width: 100%; border-collapse: collapse; } .ar th { text-align: left; font-weight: 600; padding: 7px 6px; border-top: 1px solid #999; border-bottom: 1px solid #999; }
.ar td { padding: 4.5px 6px; border-bottom: 1px solid #ddd; vertical-align: top; } .ar td:first-child { white-space: nowrap; } .ar .r { text-align: right; white-space: nowrap; }
.ar tr.head td { padding-top: 7px; border-top: 1px solid #999; border-bottom: 1px solid #999; font-weight: 500; }
.ar tr.total td { font-weight: 700; } .ar tr.grand td { font-weight: 700; font-size: 11pt; } .ar tr.gap td { border: 0; padding: 3px; }
.ar .foot { margin-top: 22px; font-size: 8pt; color: #555; display: none; } @media screen { .ar .foot { display: flex; justify-content: space-between; } }
</style><div class="ar"><div class="t"><h1>${esc(r.title)}</h1><div>${esc(r.firm)}</div><div>${esc(r.period)}</div>${r.sub ? `<div>${esc(r.sub)}</div>` : ''}</div>
<table>${hasHeads ? `<thead><tr>${r.cols.map((c) => `<th class="${c.align === 'right' ? 'r' : ''}" ${c.width ? `style="width:${c.width}"` : ''}>${esc(c.label)}</th>`).join('')}</tr></thead>` : `<thead><tr>${r.cols.map((c) => `<th style="${c.width ? 'width:' + c.width : ''}"></th>`).join('')}</tr></thead>`}<tbody>${r.rows.map(tr).join('')}</tbody></table>
<div class="foot"><span>${esc(foot)}</span><span>Page 1</span></div></div>`;
}

/** The report as spreadsheet rows (same lines as the PDF), for Excel. */
export function reportSheet(r: Report, generatedBy: string, when = new Date()): Cell[][] {
  const out: Cell[][] = [[r.title], [r.firm], [r.period.replace(' - ', ' to ')], ...(r.sub ? [[r.sub]] : []), r.cols.map((c) => c.label)];
  for (const row of r.rows) {
    if (row.style === 'gap') continue;
    out.push(row.cells.map((c, i) => (typeof c === 'number' && r.cols[i]?.label === '%' ? r2(c / 100) : c ?? '')).map((c, i) => (i === 0 && row.style === 'head' && typeof c === 'string' ? c.toUpperCase() : c)));
  }
  const stamp = dmy(when.getTime()) + ' ' + when.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', hour12: true }).replace(' ', '').toLowerCase();
  out.push([], ['Report Generated by ' + generatedBy + ' on ' + stamp + ' with SHCO Portal']);
  return out;
}
